  var v_i: u32 = (((cw_block.x + (cw_block.y * cw_grid.x)) * cw_block_size.x) + cw_thread.x);
  if ((v_i < (cw_params.p_width * cw_params.p_height))) {
    let cw_argument_index_0 = v_i;
    b_texels[((cw_params.p_offset + (((cw_params.p_height - 1u) - (v_i / cw_params.p_width)) * cw_params.p_width)) + (v_i % cw_params.p_width))] = bitcast<u32>(b_target[cw_argument_index_0]);
  }
